  "tests": [
    {
      "feature": "User Onboarding and Security",
      "scenarios": [
        {
          "name": "Successful user registration and KYC submission",
          "given": "A new user provides valid email, a strong password, and personal details",
          "when": "The user completes the registration form and uploads KYC documents",
          "then": "An account is created with 'PENDING_VERIFICATION' status and a verification email is sent"
        },
        {
          "name": "Secure login with Time-based One-Time Password (TOTP)",
          "given": "An existing, verified user has TOTP enabled",
          "when": "The user enters correct credentials and the valid TOTP code from their authenticator app",
          "then": "The system grants access and issues a JWT session token"
        },
        {
          "name": "Login attempt with invalid MFA code",
          "given": "An existing, verified user has TOTP enabled",
          "when": "The user enters correct credentials but an invalid TOTP code",
          "then": "Access is denied and an error message is displayed"
        }
      ]
    },
    {
      "feature": "Asset Funding and Withdrawal",
      "scenarios": [
        {
          "name": "Cryptocurrency deposit confirmation",
          "given": "A user has generated a unique BTC deposit address from their wallet",
          "when": "The user sends 0.5 BTC to that address and the transaction receives 6 confirmations on the Bitcoin network",
          "then": "The user's BTC balance in the exchange is credited with 0.5 BTC"
        },
        {
          "name": "Secure withdrawal to a whitelisted address",
          "given": "A user has a verified account with 1.0 ETH and a whitelisted withdrawal address",
          "when": "The user initiates a withdrawal of 0.5 ETH to the whitelisted address and confirms via email link and MFA code",
          "then": "The withdrawal request is processed by the multi-signature wallet system and the transaction is broadcast to the Ethereum network"
        },
        {
          "name": "Attempted withdrawal to a non-whitelisted address",
          "given": "A user has a security setting to 'Allow withdrawals to whitelisted addresses only'",
          "when": "The user attempts to withdraw funds to a new, non-whitelisted address",
          "then": "The withdrawal is blocked and the user is prompted to add and verify the new address"
        }
      ]
    },
    {
      "feature": "Trading Core Functionality",
      "scenarios": [
        {
          "name": "Placing and filling a limit buy order",
          "given": "User A has a balance of 10,000 USDT and the BTC/USDT market price is 50,000",
          "when": "User A places a limit buy order for 0.1 BTC at a price of 49,500 USDT, and User B places a market sell order for 0.1 BTC",
          "then": "The matching engine matches the orders, User A's BTC balance increases by 0.1 and USDT balance decreases by 4,950, and User B's balances are updated accordingly"
        },
        {
          "name": "Partial fill of a limit sell order",
          "given": "User C places a limit sell order for 10 ETH at 3,000 USDT/ETH",
          "when": "A buyer places a market buy order for 4 ETH",
          "then": "User C's order is partially filled, their open order is now for 6 ETH, and their USDT balance is credited for the 4 ETH sold"
        },
        {
          "name": "Order rejection due to insufficient funds",
          "given": "A user has a balance of 1,000 USDT",
          "when": "The user attempts to place a limit buy order for 0.5 BTC at a price of 50,000 USDT (total cost 25,000 USDT)",
          "then": "The order is rejected by the system with an 'Insufficient Funds' error"
        }
      ]
    },
    {
      "feature": "Real-time Dashboard",
      "scenarios": [
        {
          "name": "Order book updates in real-time",
          "given": "A user is viewing the BTC/USDT trading dashboard",
          "when": "Another user places a new limit order",
          "then": "The order book visualization on the dashboard updates via WebSocket push within 200ms to show the new order's price and quantity"
        },
        {
          "name": "Portfolio balance updates instantly after a trade",
          "given": "A user is viewing their portfolio on the dashboard",
          "when": "One of the user's open orders is filled",
          "then": "The asset balances in the portfolio component update immediately without requiring a page refresh"
        }
      ]
    },
    {
      "feature": "Compliance and Auditing",
      "scenarios": [
        {
          "name": "AML system flags a suspicious transaction pattern",
          "given": "The compliance service is monitoring all transactions",
          "when": "A user makes multiple high-value deposits from different unverified wallets in a short period, exceeding a predefined risk threshold",
          "then": "The compliance service flags the user's account, temporarily freezes withdrawals, and creates an alert for a compliance officer to review"
        },
        {
          "name": "CI/CD pipeline blocks deployment of an unaudited smart contract",
          "given": "The CI/CD pipeline has a mandatory 'Smart Contract Audit' stage",
          "when": "A developer commits a new smart contract to the repository without a corresponding successful audit report from the audit-service",
          "then": "The pipeline fails at the audit gate, preventing deployment to any environment"
        }
      ]
    }
